/* =========================================================
   小小注音冒險家 - iOS/iPadOS 記憶體防卡死音效池 (Audio Pool)
   ========================================================= */

// 1. 建立固定數量的 Audio 實體池（全域重複利用，徹底阻止 iOS 記憶體暴增）
const SFX_POOL_SIZE = 6;
const sfxPool = Array.from({ length: SFX_POOL_SIZE }, () => new Audio());
let currentSfxIndex = 0;

/**
 * 內部核心：從音效池取用實體播放（0 記憶體消耗）
 */
function playFromPool(src, volume = 1.0) {
  if (!src) return;
  try {
    // 輪替取用池中的 Audio 實體
    const audio = sfxPool[currentSfxIndex];
    currentSfxIndex = (currentSfxIndex + 1) % SFX_POOL_SIZE;

    audio.pause();
    audio.currentTime = 0; // 重置時間點
    audio.volume = volume;
    audio.src = src;

    const playPromise = audio.play();
    if (playPromise !== undefined) {
      playPromise.catch(e => console.log('SFX play blocked or interrupted:', e));
    }
  } catch (e) {
    console.error('Audio pool error:', e);
  }
}

/* =========================================================
   對接函式重構（函式名稱與參數完全不變，對外零衝擊）
   ========================================================= */

// 1. 按鈕點擊 / 叮叮音效
function playDing() {
  if (typeof DING_SOUND !== 'undefined') {
    playFromPool(DING_SOUND, 0.3);
  }
}

// 2. 注音符號語音朗讀
function speak(symbol) {
  if (typeof ZHUYIN_AUDIO_MAP !== 'undefined' && ZHUYIN_AUDIO_MAP[symbol]) {
    playFromPool(ZHUYIN_AUDIO_MAP[symbol], 1.0);
  }
}

// 3. 答對 / 答錯音效
function playSfx(type) {
  if (type === 'correct' && typeof SOUND_SUCCESS_BASE64 !== 'undefined') {
    playFromPool(SOUND_SUCCESS_BASE64, 0.4);
  } else if (type === 'wrong' && typeof SOUND_WRONG_BASE64 !== 'undefined') {
    playFromPool(SOUND_WRONG_BASE64, 0.7);
  }
}

const SOUND_SUCCESS_BASE64 = "data:audio/mp3;base64,";








const SOUND_WRONG_BASE64 = "data:audio/mp3;base64,";











